/**
 * Snowflake Node - Version 1
 * Get, add and update data in Snowflake
 */


export interface SnowflakeV1Params {
  authentication?: 'credentials' | 'oAuth2' | Expression<string>;
  operation?: 'executeQuery' | 'insert' | 'update';
/**
 * The SQL query to execute. Use ? (bound in order) or :1, :2, :3 to refer to the 'Query Parameters' set in the options below.
 * @hint Consider using query parameters to prevent SQL injection attacks. Add them in the options below
 * @displayOptions.show { operation: ["executeQuery"] }
 */
    query: string;
/**
 * Options
 * @displayOptions.show { operation: ["executeQuery"] }
 * @default {}
 */
    options?: {
    /** Comma-separated list of the values you want to use as query parameters. You can drag the values from the input panel on the left.
     * @hint Comma-separated list of values: reference them in your query as ? (in order) or :1, :2, :3…
     */
    queryReplacement?: string | Expression<string>;
  };
/**
 * Name of the table in which to insert data to
 * @displayOptions.show { operation: ["insert"] }
 */
    table: string | Expression<string>;
/**
 * Comma-separated list of the properties which should used as columns for the new rows
 * @displayOptions.show { operation: ["insert"] }
 */
    columns?: string | Expression<string>;
/**
 * Name of the property which decides which rows in the database should be updated. Normally that would be "id".
 * @displayOptions.show { operation: ["update"] }
 * @default id
 */
    updateKey?: string | Expression<string>;
}

export interface SnowflakeV1Credentials {
  snowflake: CredentialReference;
  snowflakeOAuth2Api: CredentialReference;
}

interface SnowflakeV1NodeBase {
  type: 'n8n-nodes-base.snowflake';
  version: 1;
}

export type SnowflakeV1ParamsNode = SnowflakeV1NodeBase & {
  config: NodeConfig<SnowflakeV1Params> & { credentials?: SnowflakeV1Credentials };
};

export type SnowflakeV1Node = SnowflakeV1ParamsNode;